assert 400 * 15 - 3500 == 2500
b.add(T, "apply", "นักเรียนปลูกผักบุ้งขาย ลงทุนค่าเมล็ด ปุ๋ย และวัสดุรวม 3,500 บาท เก็บผลผลิตได้ 400 กิโลกรัม ขายกิโลกรัมละ 15 บาท ได้กำไรเท่าใด",
      "2,500 บาท", ["6,000 บาท", "3,500 บาท", "9,500 บาท"],
      "รายรับ = 400 × 15 = 6,000 บาท กำไร = รายรับ − ต้นทุน = 6,000 − 3,500 = 2,500 บาท "
      "ตัวลวง 6,000 คือรายรับ ยังไม่หักต้นทุน การทำบัญชีรายรับรายจ่ายช่วยให้นักเรียนเห็นผลการดำเนินงานจริง", sub=BIZ)
assert 6000 / (25 - 10) == 400
b.add(T, "apply", "การเพาะเห็ดนางฟ้าขายมีต้นทุนคงที่ (โรงเรือน อุปกรณ์) 6,000 บาท ต้นทุนผันแปร 10 บาทต่อกิโลกรัม ขายได้กิโลกรัมละ 25 บาท ต้องขายกี่กิโลกรัมจึงถึงจุดคุ้มทุน",
      "400 กิโลกรัม", ["240 กิโลกรัม", "600 กิโลกรัม", "171 กิโลกรัม"],
      "แต่ละกิโลกรัมได้ส่วนเกินไว้คืนต้นทุนคงที่ 25 − 10 = 15 บาท จุดคุ้มทุน = 6,000 ÷ 15 = 400 กิโลกรัม "
      "ตัวลวง 240 มาจาก 6,000 ÷ 25 ซึ่งลืมหักต้นทุนผันแปร ส่วน 600 มาจาก 6,000 ÷ 10", sub=BIZ)
